<?php
// Prévia de montagem: não recebe pedidos nem altera carrinho.
require_once __DIR__.'/sistema/conexao.php';
$loja=$_GET['loja']??'';$id=filter_var($_GET['id']??null,FILTER_VALIDATE_INT);
function bc_h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
if(!is_string($loja)||!preg_match('/^[a-zA-Z0-9_-]+$/D',$loja)||!$id||$id<1){http_response_code(404);exit('Combo não encontrado.');}
try{
$q=$pdo->prepare("SELECT c.id,c.empresa,c.tipo,p.nome,p.foto,p.descricao,p.valor_venda,p.promocao,p.val_promocional FROM combo_configuracoes c JOIN produtos p ON p.id=c.produto_combo_id AND p.empresa=c.empresa JOIN config l ON l.empresa=c.empresa WHERE l.url_site=? AND c.produto_combo_id=? AND c.ativo='Sim' AND p.ativo='Sim' AND p.combo='Sim' AND p.delivery='Sim' AND (p.tem_estoque='Não' OR p.estoque>0) LIMIT 1");
$q->execute([$loja,$id]);$c=$q->fetch(PDO::FETCH_ASSOC);
if(!$c){http_response_code(404);exit('Combo indisponível.');}
$q=$pdo->prepare('SELECT * FROM combo_grupos WHERE empresa=? AND combo_configuracao_id=? ORDER BY ordem,id');$q->execute([$c['empresa'],$c['id']]);$grupos=$q->fetchAll(PDO::FETCH_ASSOC);
$q=$pdo->prepare("SELECT i.id,i.acrescimo,p.nome,p.foto FROM combo_grupo_produtos i JOIN produtos p ON p.id=i.produto_id AND p.empresa=i.empresa WHERE i.empresa=? AND i.combo_grupo_id=? AND p.ativo='Sim' AND COALESCE(p.combo,'Não')<>'Sim' AND (p.tem_estoque='Não' OR p.estoque>0) AND i.acrescimo>=0 ORDER BY i.ordem,i.id");
$disponivel=(bool)$grupos;
foreach($grupos as &$g){$q->execute([$c['empresa'],$g['id']]);$g['itens']=$q->fetchAll(PDO::FETCH_ASSOC);if(count($g['itens'])<(int)$g['minimo'] || ($c['tipo']==='fixo' && count($g['itens'])!==(int)$g['maximo']))$disponivel=false;}unset($g);
}catch(Throwable $e){http_response_code(503);exit('Montagem temporariamente indisponível.');}
$base=(int)round(100*(($c['promocao']==='Sim' && $c['val_promocional']>0)?$c['val_promocional']:$c['valor_venda']));
function bc_money($n){return 'R$ '.number_format($n/100,2,',','.');}
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Montar combo</title><style>
*{box-sizing:border-box}body{margin:0;background:#fcf7f0;color:#512c24;font:16px system-ui,sans-serif}header{position:sticky;top:0;background:#fff8ef;border-bottom:1px solid #ead3bc;padding:12px;z-index:2}header div,main{max-width:960px;margin:auto}header a{color:#82451f;text-decoration:none;font-weight:700}main{padding:16px 12px 32px}section{background:#fffdf9;border:1px solid #efddc9;border-radius:16px;padding:16px;margin-bottom:16px}h1,h2,p{margin:0 0 10px}h2{font-size:19px}.hero{display:flex;gap:16px;align-items:center}.hero img{width:112px;height:112px;object-fit:cover;border-radius:12px}.option{display:flex;align-items:center;gap:12px;padding:12px 0;border-top:1px solid #efddc9;cursor:pointer}.option img{width:52px;height:52px;object-fit:cover;border-radius:8px}.option input{width:20px;height:20px;accent-color:#a85b24}.option strong{flex:1}.price{color:#a85b24;font-weight:700}.summary{max-width:420px;margin:auto;text-align:center}.summary button{width:100%;padding:14px;border:0;border-radius:12px;background:#a85b24;color:white;font:inherit;opacity:.65}.notice{background:#fff0df;padding:12px;border-radius:10px}small{color:#806e60}@media(max-width:480px){.hero img{width:84px;height:84px}h1{font-size:21px}.option{gap:8px}.option img{width:44px;height:44px}}
</style></head><body><header><div><a href="/site/<?=bc_h(rawurlencode($loja))?>#combo">← Voltar aos combos</a></div></header><main><section class="hero"><img src="/media-delivery.php?tipo=produtos&amp;arquivo=<?=bc_h(rawurlencode($c['foto']))?>" alt=""><div><h1><?=bc_h($c['nome'])?></h1><p><?=bc_h($c['descricao'])?></p><strong class="price"><?=bc_money($base)?></strong></div></section><p class="notice">Prévia de montagem — pedidos ainda não habilitados.</p>
<?php if(!$disponivel):?><p class="notice">Não há produtos suficientes para montar este combo agora.</p><?php endif;?>
<?php foreach($grupos as $g):?><section class="group" data-min="<?=(int)$g['minimo']?>" data-max="<?=(int)$g['maximo']?>"><h2><?=bc_h($g['nome'])?></h2><p><small>Escolha de <?=(int)$g['minimo']?> a <?=(int)$g['maximo']?> · <span class="count"></span></small></p><?php foreach($g['itens'] as $i):?><label class="option"><input type="checkbox" data-extra="<?=(int)round(100*$i['acrescimo'])?>" <?=$c['tipo']==='fixo'?'checked disabled':''?>><img src="/media-delivery.php?tipo=produtos&amp;arquivo=<?=bc_h(rawurlencode($i['foto']))?>" alt=""><strong><?=bc_h($i['nome'])?></strong><span class="price"><?=$i['acrescimo']>0?'+ '.bc_money((int)round(100*$i['acrescimo'])):'Incluso'?></span></label><?php endforeach;?></section><?php endforeach;?>
<section class="summary"><h2>Total: <span id="total"></span></h2><p id="status" aria-live="polite"></p><button disabled>Adicionar ao carrinho — em breve</button></section></main><script>
const base=<?=$base?>,available=<?=$disponivel?'true':'false'?>,fixed=<?=$c['tipo']==='fixo'?'true':'false'?>;
function update(){let total=base,valid=available;document.querySelectorAll('.group').forEach(g=>{const boxes=[...g.querySelectorAll('input')],selected=boxes.filter(b=>b.checked),n=selected.length,max=Number(g.dataset.max);g.querySelector('.count').textContent=n+' selecionado(s)';boxes.forEach(b=>{b.disabled=fixed||(!b.checked&&n>=max)});selected.forEach(b=>total+=Number(b.dataset.extra));if(n<Number(g.dataset.min)||n>max)valid=false;});document.getElementById('total').textContent=(total/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});document.getElementById('status').textContent=valid?'Seleção completa.':'Confira as escolhas obrigatórias.';}document.addEventListener('change',update);update();
</script></body></html>